import ssh2 from 'ssh2';
import YAML from 'yaml';
import { fingerprintOf } from '../remote.js';

const { utils } = ssh2;

/**
 * cloud-init for a bot VM, generated by TeamBot (CMP-07 part 2).
 *
 * - The SSH host key is generated by TeamBot (`ssh_keys.ed25519_*` + `ssh_deletekeys`, no other key types), so its
 *   fingerprint is pinned before the VM even exists: no trust-on-first-use.
 * - One login: user `teambot`, no sudo, locked password, only TeamBot's fresh client key. Root is locked, password and
 *   keyboard-interactive logins are off, only `teambot` may log in.
 * - The host private key has to be in the user data. After the first boot the local copies are removed and the
 *   provider's metadata service (where the user data stays readable from inside the VM) is blocked for `teambot`.
 * - Nothing else goes in: no API token, no client private key, no TeamBot settings.
 */

export interface KeyPair {
  private: string;
  public: string;
  fingerprint: string;
}

/**
 * Fresh ed25519 key pair in OpenSSH format. ssh2's generator now and then produces a key its own parser rejects, so
 * every pair is parsed back (private and public, and both must have the same public key) and regenerated if needed.
 */
export function genKeyPair(comment: string): KeyPair {
  for (let i = 0; i < 25; i++) {
    const k = utils.generateKeyPairSync('ed25519', { comment });
    const priv = utils.parseKey(k.private);
    const pub = utils.parseKey(k.public);
    if (priv instanceof Error || pub instanceof Error) continue;
    const p = Array.isArray(priv) ? priv[0] : priv;
    const q = Array.isArray(pub) ? pub[0] : pub;
    if (!p?.isPrivateKey() || !q || !p.getPublicSSH().equals(q.getPublicSSH())) continue;
    return { private: k.private.trim() + '\n', public: k.public.trim(), fingerprint: fingerprintOf(q.getPublicSSH()) };
  }
  throw new Error('Kon geen bruikbaar SSH-sleutelpaar maken.');
}

/** The well-known link-local metadata address (Hetzner, and most clouds). */
export const METADATA_IP = '169.254.169.254';

const CLEANUP =
  'rm -f /var/lib/cloud/instance/user-data.txt /var/lib/cloud/instance/user-data.txt.i /var/lib/cloud/instance/cloud-config.txt /var/lib/cloud/instance/obj.pkl ' +
  '/var/lib/cloud/instances/*/user-data.txt /var/lib/cloud/instances/*/user-data.txt.i /var/lib/cloud/instances/*/cloud-config.txt /var/lib/cloud/instances/*/obj.pkl ' +
  '/run/cloud-init/instance-data-sensitive.json /run/cloud-init/combined-cloud-config.json';

export function buildCloudInit(o: { hostKey: KeyPair; clientPublicKey: string; docker: boolean; label: string }): string {
  const sshdConf = ['# Written by TeamBot cloud-init', 'PasswordAuthentication no', 'KbdInteractiveAuthentication no', 'PermitRootLogin no', 'AllowUsers teambot', 'HostKey /etc/ssh/ssh_host_ed25519_key', ''].join('\n');
  const cfg: Record<string, any> = {
    ssh_deletekeys: true,
    ssh_genkeytypes: [],
    ssh_keys: { ed25519_private: o.hostKey.private, ed25519_public: o.hostKey.public },
    ssh_pwauth: false,
    disable_root: true,
    users: [
      {
        name: 'teambot',
        gecos: 'TeamBot',
        shell: '/bin/bash',
        lock_passwd: true,
        ssh_authorized_keys: [o.clientPublicKey.trim()],
        ...(o.docker ? { groups: ['docker'] } : {}),
      },
    ],
    write_files: [{ path: '/etc/ssh/sshd_config.d/10-teambot.conf', owner: 'root:root', permissions: '0644', content: sshdConf }],
    ...(o.docker ? { package_update: true, packages: ['docker.io'] } : {}),
    runcmd: [
      'passwd -l root',
      // the user data (with the host private key) stays available via the metadata service: not for the bot's user
      `iptables -I OUTPUT -d ${METADATA_IP} -m owner --uid-owner teambot -j REJECT || true`,
      `ip6tables -I OUTPUT -d fe80::a9fe:a9fe -m owner --uid-owner teambot -j REJECT 2>/dev/null || true`,
      ...(o.docker ? ['usermod -aG docker teambot || true', 'systemctl enable --now docker || true'] : []),
      'systemctl restart ssh 2>/dev/null || systemctl restart sshd 2>/dev/null || true',
      // remove the local copies of the user data and the cached datasource (they contain the host private key); once
      // now and once more after cloud-init has finished (it may write its cache again at the end of a stage)
      CLEANUP,
      `systemd-run --on-active=120 --unit=teambot-userdata-cleanup /bin/sh -c ${JSON.stringify(CLEANUP)} || true`,
    ],
  };
  const header = `#cloud-config\n# TeamBot bot computer: ${o.label.replace(/[\r\n]/g, ' ').slice(0, 80)}\n`;
  return header + YAML.stringify(cfg, { lineWidth: 0 });
}
